<?php
/**
 * Environment-aware WordPress configuration.
 *
 * Order: Pantheon (wp-config-pantheon.php, committed; do not edit) -> DDEV
 * (wp-config-ddev.php, generated by DDEV) -> local secrets (wp-config-local.php, gitignored).
 * No secrets are committed in this file.
 *
 * @package tyler-cms
 */

if ( file_exists( __DIR__ . '/wp-config-local.php' ) && ! isset( $_ENV['PANTHEON_ENVIRONMENT'] ) ) {
	require_once __DIR__ . '/wp-config-local.php';
}

if ( isset( $_ENV['PANTHEON_ENVIRONMENT'] ) ) {
	// Committed in this repo (copied from pantheon-systems/WordPress); supplies DB creds and salts from the environment.
	if ( ! file_exists( __DIR__ . '/wp-config-pantheon.php' ) ) {
		// Fail loudly: falling through gives a misleading "Error establishing a database connection".
		header( 'HTTP/1.1 500 Internal Server Error' );
		exit( 'Configuration error: wp-config-pantheon.php is missing from the codebase.' );
	}
	require_once __DIR__ . '/wp-config-pantheon.php';
} elseif ( getenv( 'IS_DDEV_PROJECT' ) === 'true' && is_readable( __DIR__ . '/wp-config-ddev.php' ) ) {
	require_once __DIR__ . '/wp-config-ddev.php';
}

defined( 'DB_CHARSET' ) || define( 'DB_CHARSET', 'utf8mb4' );
defined( 'DB_COLLATE' ) || define( 'DB_COLLATE', '' );

// Platform hardening (security.md): no code edits through wp-admin in any environment.
defined( 'DISALLOW_FILE_EDIT' ) || define( 'DISALLOW_FILE_EDIT', true );

// Pantheon Test/Live code is read-only; block installs/updates there but allow on DDEV and Dev (SFTP).
if ( isset( $_ENV['PANTHEON_ENVIRONMENT'] ) && in_array( $_ENV['PANTHEON_ENVIRONMENT'], array( 'test', 'live' ), true ) ) {
	defined( 'DISALLOW_FILE_MODS' ) || define( 'DISALLOW_FILE_MODS', true );
}

defined( 'WP_ENVIRONMENT_TYPE' ) || define(
	'WP_ENVIRONMENT_TYPE',
	isset( $_ENV['PANTHEON_ENVIRONMENT'] )
		? ( 'live' === $_ENV['PANTHEON_ENVIRONMENT'] ? 'production' : ( 'test' === $_ENV['PANTHEON_ENVIRONMENT'] ? 'staging' : 'development' ) )
		: 'local'
);

defined( 'WP_DEBUG' ) || define( 'WP_DEBUG', 'local' === WP_ENVIRONMENT_TYPE );
defined( 'WP_DEBUG_DISPLAY' ) || define( 'WP_DEBUG_DISPLAY', false );
defined( 'WP_DEBUG_LOG' ) || define( 'WP_DEBUG_LOG', WP_DEBUG );

$table_prefix = getenv( 'DB_TABLE_PREFIX' ) ?: 'wp_'; // phpcs:ignore WordPress.WP.GlobalVariablesOverride.Prohibited

defined( 'ABSPATH' ) || define( 'ABSPATH', __DIR__ . '/' );
require_once ABSPATH . 'wp-settings.php';
